use vstd::prelude::*;

verus! {

// Helper spec function: returns true if `c` is an ASCII letter (a-z or A-Z).
spec fn is_ascii_letter(c: char) -> bool {
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

// Specification function that models the behavior on a sequence of chars.
// txt_chars represents the Unicode scalar values of the input string.
spec fn check_last_char_letter(txt_chars: Seq<char>) -> bool {
    // Non-empty condition
    txt_chars.len() > 0
    // Last character is ASCII letter
    && is_ascii_letter(txt_chars.index(txt_chars.len() - 1))
    // Either length is exactly 1,
    // or the preceding character is ' ' (space)
    && (txt_chars.len() == 1 
        || txt_chars.index(txt_chars.len() - 2) == ' ')
}

// Helper spec function to model string as sequence of chars
spec fn string_chars(s: &str) -> Seq<char> {
    s@.to_seq()
}

fn check_if_last_char_is_a_letter(txt: &str) -> (result: bool)
    ensures
        result == check_last_char_letter(string_chars(txt))
{
    let txt_chars = txt@.to_seq();
    
    if txt.len() == 0 {
        return false;
    }
    
    let chars: Vec<char> = txt.chars().collect();
    let len = chars.len();
    
    assert(chars@.len() == txt_chars.len());
    
    if len == 0 {
        return false;
    }
    
    let last_char = chars[len - 1];
    
    assert(last_char == txt_chars.index((len - 1) as int));
    
    let is_letter = ('a' <= last_char && last_char <= 'z') 
                 || ('A' <= last_char && last_char <= 'Z');
    
    if !is_letter {
        return false;
    }
    
    if len == 1 {
        return true;
    }
    
    let prev_char = chars[len - 2];
    assert(prev_char == txt_chars.index((len - 2) as int));
    
    prev_char == ' '
}

}

